def get_svg_icon(name: str, color: str = "#00F2FE", size: int = 20) -> QIcon:
    """
    Generates a QIcon from SVG template with custom stroke color and size.
    """
    svg_template = SVG_ICONS.get(name, SVG_ICONS["folder"])
    svg_data = svg_template.format(color=color).encode("utf-8")
    
    renderer = QSvgRenderer(QByteArray(svg_data))
    pixmap = QPixmap(size, size)
    pixmap.fill(QColor(0, 0, 0, 0))
    
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()
    
    return QIcon(pixmap)
